# item `source` field (EmberItemData.SOURCES) — decides dismantle / duplicate eligibility
item_sources:
  drop:    {meaning: "settlement random roll, raid_item, chest extra, 8-mark exchange (mark_item)", dismantle: true, code: ["p1/EmberRunService.java#: \"drop\""]}
  quest:   {meaning: "first-clear choice item (fc_<map>_item) / starter kit (starter_<slot>)", dismantle: false, code: ["p1/EmberRunService.java#startsWith(\"starter_\") ? \"quest\""]}
  admin:   {meaning: "/corerpg p1 give / givedup (OP test items); never counts for the codex; givedup may feed the reroll duplicate (D243)", dismantle: false, code: ["p1/EmberCommand.java#\"admin\""]}
  reissue: {meaning: "manual re-issue by staff", dismantle: false, code: ["p1/EmberCompare.java#\"reissue\""]}
  migrate: {meaning: "legacy migration (none on live: no old players)", dismantle: false, code: ["p1/EmberCompare.java#\"migrate\""]}

# item provenance (D245 · ARCH systems-map step 4) — WHERE a piece came from, stored on the item next to the D208 keys.
# Behaviour-neutral: no stat / lore / dismantle / codex rule reads it; shown to OPs only (/corerpg p1 inspect). Pieces made before
# 1.65.70 have no origin and stay valid (their canonical / HMAC bytes are unchanged; v2 canonical appends "|o:<packed>" only when
# present). The DB column is never wiped by a later write (UPDATE / upsert keep a non-empty origin).
item_provenance:
  nbt: {om: "map / mode id (lower [a-z0-9_], ≤ 24)", os: "source row S## / X##", or: "run id / request id (≤ 48)", ot: "unix seconds (int)"}
  column: "cr_p1_item.origin VARCHAR(128) NOT NULL DEFAULT ''"
  packed: "map|src|run|at"
  unknown_source: X00
  code: ["p1/EmberProvenance.java#public static EmberItemData.Origin forReward(", "p1/EmberItemData.java#public static final class Origin", "p1/EmberItemStore.java#\"origin\", \"VARCHAR(128) NOT NULL DEFAULT ''\"", "p1/EmberRunService.java#EmberProvenance.forReward(g.key, row.runId, row.created)"]
  rules:  # example = [ledger reward key, ledger run id] → expected map / src (pinned by EmberSourceMapTest.itemProvenanceMatchesCode)
    base_item:      {example: [base_item, q01-k3x9a-1b2c], map: q01, src: S01, meaning: "settlement random roll (normal / repeat)"}
    challenge_item: {example: [base_item, q03c-k3x9a-1b2c], map: q03c, src: S01, meaning: "challenge settlement roll"}
    abyss_item:     {example: [base_item, q05a2-k3x9a-1b2c], map: q05a2, src: S13, meaning: "abyss floor settlement roll"}
    chest_item:     {example: [extra_chest_item, q02-k3x9a-1b2c], map: q02, src: S34, meaning: "chest extra roll"}
    raid_item:      {example: [raid_item, r01-k3x9a-1b2c], map: r01, src: S12, meaning: "raid settlement piece"}
    fc_item:        {example: [fc_q01_blade_item, q01-k3x9a-1b2c], map: q01, src: S06, meaning: "first-clear choice piece"}
    starter:        {example: [starter_blade, starter], map: starter, src: S35, meaning: "T0 starter kit"}
    mark_redeem:    {map: forge, src: S28, meaning: "8-mark exchange (run = payment request id)", code: ["p1/EmberRunService.java#EmberProvenance.forRedeem(rid"]}
    admin:          {map: admin, src: X03, meaning: "/corerpg p1 give / givedup (run = give / givedup)", code: ["p1/EmberCommand.java#EmberProvenance.forAdmin(\"give\"", "p1/EmberCommand.java#EmberProvenance.forAdmin(\"givedup\""]}

