    pays: [coin, shard, bone, core, xp, mark, gear]
    period: run
    content: [q01, q02, q03, q04, q05, q06, q07, challenge, r01, r02, r03]
    drop_table: "gear: EmberRunRules.rollItem — family TARGET_WEIGHT 0.60 + loot_bias (own_family / map_share / slot), quality QUALITY_WEIGHTS 70/23/6/1 (challenge & raid 60/28/10/2), craft CRAFT_WEIGHTS 70/20/9/1, tier = map tier"
