# ---------------------------------------------------------------------------------------------------- stocks (D244 / G10)
# Item-level stocks: where the balance lives, which registered rows add to it (rows_in — incl. sinks that convert into it)
# and which take from it (rows_out), plus the item ids. EmberSourceMapTest: rows_in ∪ rows_out == EmberEconomy.touching(econ),
# rows_out are sinks; life_item.items == every item in life.yml (offers / cook) + CoreFish tables that is not another
# account's ni; gacha_ticket.grants == CoreGacha config tickets keys; every gacha.yml item kind ∈ cosmetic.gacha_kinds.
stocks:
  insignia:
    econ: INSIGNIA
    store: "p1_sigmark_<map>@all (one balance per signature map, not interchangeable)"
    rows_in: [S07, S08, S09, S17, S18, S23]
    rows_out: [C12, C13]
    cap: none
    model: "tools/p1sim/insignia.py (D222, opt-in: S07/S08/S09/S17/S18/S23 → C12/C13; p2econ --insignia)"
  badge:
    econ: BADGE
    store: "p3_badge@all"
    rows_in: [S16, S19, S27]
    rows_out: [C15, C16, C18]
    cap: "S27 exchange cap 40 (event); others uncapped"
    model: "p2econ behaviour only (earning); stock / spend not modelled — sinks C15 / C16 paused, C18 event-only"
  life_item:
    econ: LIFE_ITEM
