# CoreRpg progress — 2026-09-26（1.5.0）
# 规格来源：docs/design/DESIGN-ember-economy-monetization.md §5.3（战令经验来源 = 挂机击杀 / 日本 / 周本，有日上限）；
#   数值规格未给出，以下为保守取值。

# 第二经验等级来源：MM 精英/首领死亡 → console: corerpg xpreward <trigger.name> elite|boss
kill_levels:
  enabled: true
  levels:
    elite: 1
    boss: 2
  daily_cap: 6          # 每人每日最多 +6 级（日本 3 次 ×3 级 = 9；附魔 1~3 级/次、修理 2 级/片）

# 战令赛季经验：签到（内部）+ DP 通关箱 console: corerpg progress %player_name% <source>（同时给战令经验与余烬经验）
pass_xp:
  enabled: true
  sources:
    sign: 10
    daily_clear: 20
    weekly_clear: 40
    abyss_clear: 20
    raid_clear: 40
    guild_boss_clear: 20
    bounty: 15           # 1.7.0 悬赏（每日 1 次领取）
    elite_weekly: 15     # 4.4 精英试炼通关（周 1；计入战令日顶）
  daily_cap: 120        # 2026-09-27 (critic): was 100/100 → 30 days with zero misses
  xp_per_level: 80      # 2400 total: active F2P (~85–105/day) ≈ 23–28 days, casual ≈ Lv17
  max_level: 30

# ---------------------------------------------------------------------------
# 1.6.0 余烬等级（DESIGN-ember-growth-curve §1：emberLevel 1～60，新号 10；天赋 1 点/级，talent.yml）
#   曲线规格未给数值 → 保守：升到下一级所需 = base + step × max(0, 等级 − step_from)
#   Lv10→11 需 60，Lv30→31 需 300，Lv59→60 需 648；Lv10→60 合计 17,700。
#   满勤约 450～500/日（签到 20 + 日本 3×60 + 精英/首领约 50 + 击杀 100 + 周/团/深渊/盟 摊到每日约 100）
#   → 满勤约 5～6 周满级，休闲（~200/日）约 3 个月。
ember_xp:
  enabled: true
  max_level: 60
  curve:
    base: 60
    step: 12
    step_from: 10
  sources:
    sign: 20
    daily_clear: 60
    weekly_clear: 200
    abyss_clear: 80
    raid_clear: 250
    guild_boss_clear: 100
    bounty: 40           # 1.7.0 悬赏（每日 1 次领取 → 日上限 40）
    elite_weekly: 80     # 4.4 精英试炼通关（周 1；门控防重复）
    elite: 15
    boss: 40
    kill: 2              # 任意合格击杀（挂机庭等），受 kill_daily_cap
  kill_daily_cap: 100    # 击杀经验日软顶（= 50 只）
  combat_daily_cap: 150  # 精英/首领经验日软顶

